type (
	// Filter is the interface that wraps the Where function
	// for filtering nodes in queries and mutations.
	Filter interface {
		// Where applies a filter on the executed query/mutation.
		Where(entql.P)
	}

	// The FilterFunc type is an adapter that allows the use of ordinary
	// functions as filters for query and mutation types.
	FilterFunc func(context.Context, Filter) error
)

// EvalQuery calls f(ctx, q) if the query implements the Filter interface, otherwise it is denied.
func (f FilterFunc) EvalQuery(ctx context.Context, q dao.Query) error {
	fr, err := queryFilter(q)
	if err != nil {
		return err
	}
	return f(ctx, fr)
}

// EvalMutation calls f(ctx, q) if the mutation implements the Filter interface, otherwise it is denied.
func (f FilterFunc) EvalMutation(ctx context.Context, m dao.Mutation) error {
	fr, err := mutationFilter(m)
	if err != nil {
		return err
	}
	return f(ctx, fr)
}

var _ QueryMutationRule = FilterFunc(nil)

func queryFilter(q dao.Query) (Filter, error) {
	switch q := q.(type) {
	case *dao.APITokenQuery:
		return q.Filter(), nil
	case *dao.AnalysisJobQuery:
		return q.Filter(), nil
	case *dao.AnalysisRunQuery:
		return q.Filter(), nil
	case *dao.ChannelConfigQuery:
		return q.Filter(), nil
	case *dao.ChannelModelQuery:
		return q.Filter(), nil
	case *dao.ChannelProbeRunQuery:
		return q.Filter(), nil
	case *dao.DatasetQuery:
		return q.Filter(), nil
	case *dao.DatasetExampleQuery:
		return q.Filter(), nil
	case *dao.EvalRunQuery:
		return q.Filter(), nil
	case *dao.ExecutionEventQuery:
		return q.Filter(), nil
	case *dao.ExperimentRunQuery:
		return q.Filter(), nil
	case *dao.ModelCatalogQuery:
		return q.Filter(), nil
	case *dao.ParseJobQuery:
		return q.Filter(), nil
	case *dao.ParserVersionQuery:
		return q.Filter(), nil
	case *dao.RequestAuditQuery:
		return q.Filter(), nil
	case *dao.ResponseQuery:
		return q.Filter(), nil
	case *dao.ResponseItemQuery:
		return q.Filter(), nil
	case *dao.ScoreQuery:
		return q.Filter(), nil
	case *dao.SemanticNodeQuery:
		return q.Filter(), nil
	case *dao.SystemEventQuery:
		return q.Filter(), nil
	case *dao.ToolCallAuditQuery:
		return q.Filter(), nil
	case *dao.TraceFindingQuery:
		return q.Filter(), nil
	case *dao.TraceLogQuery:
		return q.Filter(), nil
	case *dao.TraceObservationQuery:
		return q.Filter(), nil
	case *dao.UpstreamExchangeQuery:
		return q.Filter(), nil
	case *dao.UpstreamModelQuery:
		return q.Filter(), nil
	case *dao.UpstreamTargetQuery:
		return q.Filter(), nil
	case *dao.UserQuery:
		return q.Filter(), nil
	default:
		return nil, Denyf("dao/privacy: unexpected query type %T for query filter", q)
	}
}

